import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"Git y flujo de trabajo — Disciplina que escala","description":"Estrategia de ramas, disciplina de revisión, commits convencionales y hábitos de CI para desarrollo individual y en equipo con agentes.","frontmatter":{"title":"Git y flujo de trabajo — Disciplina que escala","description":"Estrategia de ramas, disciplina de revisión, commits convencionales y hábitos de CI para desarrollo individual y en equipo con agentes."},"headers":[],"relativePath":"es/skills/git/index.md","filePath":"es/skills/git/index.md"}`),a={name:`es/skills/git/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="git-y-flujo-de-trabajo-—-disciplina-que-escala" tabindex="-1">Git y flujo de trabajo — Disciplina que escala <a class="header-anchor" href="#git-y-flujo-de-trabajo-—-disciplina-que-escala" aria-label="Permalink to “Git y flujo de trabajo — Disciplina que escala”">​</a></h1><p>Git es el contrato entre mi yo pasado, mi yo futuro y los agentes que trabajan en mi nombre. Mis reglas de flujo son lo bastante simples para seguirlas a las 2 AM y lo bastante estrictas para que los diffs generados por agentes sigan siendo revisables.</p><h2 id="las-reglas" tabindex="-1">Las reglas <a class="header-anchor" href="#las-reglas" aria-label="Permalink to “Las reglas”">​</a></h2><ul><li><strong>Ramas pequeñas de propósito único.</strong> Una idea por rama — humana o de agente.</li><li><strong>Commits convencionales.</strong> <code>feat:</code>, <code>fix:</code>, <code>refactor:</code> — el changelog se escribe solo.</li><li><strong>Revisa todo.</strong> Especialmente código de agentes; la confianza se concede por diff, nunca por herramienta.</li><li><strong>main sigue desplegable.</strong> Si main se rompe, arreglarlo supera todo lo demás.</li><li><strong>Tags para releases.</strong> Cada estado enviado es recuperable para siempre.</li></ul><p>Con agentes en el ciclo esta disciplina deja de ser opcional: tres sandboxes produciendo diffs en paralelo solo funciona si el historial se mantiene limpio y cada cambio está aislado. El <a href="/Usf/es/about/how-i-work/">método agéntico</a> depende de que git sea aburrido y predecible — exactamente lo que quiero de la infraestructura.</p>`,5)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};